/** Names lookup found per MusicBrainz ID: stored on the import document and frozen into a publication. */
export type ImportMusicBrainzNames = { musicBrainzId: string; names: string[] }[];
/**
 * One entry per Artist entry and the label (21 IDs) and at most 32 names per ID. An existing-Album review keeps one per identity
 * and the label instead (REVIEW_LOOKUP_LIMITS.identities + 1, 513 IDs).
 */
export const IMPORT_MUSICBRAINZ_NAME_LIMITS = Object.freeze({ ids: 21, names: 32, name: 200 });
/** Whose IDs names are kept for: an import's Album entries and label, or also a review's member entries (`review`). */
type CarriedOptions = { review?: boolean };
const idBound = (options: CarriedOptions) => options.review ? REVIEW_LOOKUP_LIMITS.identities + 1 : IMPORT_MUSICBRAINZ_NAME_LIMITS.ids;

const invisible = /[\p{Cc}\p{Cf}\p{Cs}]/u;
/** A found name as stored: NFC and trimmed, 1 to 200 characters, without control, invisible formatting or lone surrogate characters. */
export function cleanMusicBrainzName(raw: unknown): string | null {
    if (typeof raw !== 'string' || raw.length > 4 * IMPORT_MUSICBRAINZ_NAME_LIMITS.name) return null;
    const name = raw.normalize('NFC').trim();
    return name && name.length <= IMPORT_MUSICBRAINZ_NAME_LIMITS.name && !invisible.test(name) ? name : null;
}
/**
 * The IDs the draft carries, in draft order (Album entries, then the label, then, for a review, each track's Artist entries in
 * track order), once each. Malformed member lists carry nothing.
 */
const carriedIds = (draft: ImportDraftV2, options: CarriedOptions = {}): string[] => {
    const members = options.review ? (Array.isArray(draft.tracks) ? draft.tracks : []).flatMap(track => {
        const entries: unknown = track && typeof track === 'object' ? (track as { artists?: unknown }).artists : null;
        return Array.isArray(entries) ? entries.map(entry => entry && typeof entry === 'object' ? (entry as { musicBrainzId?: unknown }).musicBrainzId : null) : [];
    }) : [];
    return [...new Set([...draft.album.artists.map(entry => entry.musicBrainzId), draft.album.label?.musicBrainzId ?? null, ...members].filter((id): id is string => typeof id === 'string'))];
};
/** Appends clean names not yet present by fold, up to the per-ID bound. */
const addNames = (names: string[], raw: readonly unknown[]) => {
    for (const value of raw) {
        if (names.length >= IMPORT_MUSICBRAINZ_NAME_LIMITS.names) return;
        const name = cleanMusicBrainzName(value);
        if (name && !names.some(existing => foldImportName(existing) === foldImportName(name))) names.push(name);
    }
};
/**
 * Valid stored names per ID, for IDs the draft still carries only (with `review`, its members' entries included, within the review
 * bound); malformed input reads as no names.
 */
export function importMusicBrainzNameMap(stored: unknown, draft: ImportDraftV2, options: CarriedOptions = {}): Map<string, string[]> {
    const carried = new Set(carriedIds(draft, options)), map = new Map<string, string[]>();
    if (!Array.isArray(stored)) return map;
    for (const item of stored.slice(0, idBound(options))) {
        if (!item || typeof item !== 'object' || !Array.isArray((item as { names?: unknown }).names)) continue;
        const id = keepableMusicBrainzId((item as { musicBrainzId?: unknown }).musicBrainzId);
        if (!id || !carried.has(id) || map.has(id)) continue;
        const names: string[] = []; addNames(names, (item as { names: unknown[] }).names);
        if (names.length) map.set(id, names);
    }
    return map;
}
/**
 * The stored names of still-carried IDs merged with newly `found` ones (stored first), fold-deduplicated and bounded to 21 IDs in
 * draft order and 32 names each. A review (`review`) also keeps the IDs its members' entries carry, up to 513 IDs. Pure.
 */
export function mergeImportMusicBrainzNames(stored: unknown, found: ReadonlyMap<string, readonly string[]>, draft: ImportDraftV2, options: CarriedOptions = {}): ImportMusicBrainzNames {
    const existing = importMusicBrainzNameMap(stored, draft, options), merged: ImportMusicBrainzNames = [];
    for (const id of carriedIds(draft, options).slice(0, idBound(options))) {
        const names = [...existing.get(id) ?? []];
        addNames(names, found.get(id) ?? []);
        if (names.length) merged.push({ musicBrainzId: id, names });
    }
    return merged;
}

/** One ID a publication records (`replaces` null) or replaces on the Artist an entry credits, or on the label Organization. */
export type ImportMusicBrainzIdWrite = { scope: 'artist' | 'label'; entryKey: string | null; musicBrainzId: string; replaces: string | null };
/**
 * Which ID a frozen identity writes: a new record keeps its entry's ID unless another record holds it; a reused record without an
 * ID records it while no other record holds it; a reused record that holds a different ID keeps it unless the administrator chose
 * `replace`, which needs a record holding another ID and no record holding the new one. 'invalid' only for a replace that is not
 * allowed (a stale review). Pure.
 */
export function musicBrainzIdWriteFor(input: { entryId: string | null; action: 'reuse' | 'replace' | 'create-distinct'; recordId: string | null;
    recordStoredId: string | null; exactHolderId: string | null }): { musicBrainzId: string; replaces: string | null } | null | 'invalid' {
    const { entryId, action, recordId, recordStoredId, exactHolderId } = input;
    if (entryId === null) return action === 'replace' ? 'invalid' : null;
    if (action === 'create-distinct') return exactHolderId ? null : { musicBrainzId: entryId, replaces: null };
    if (action === 'replace') return recordStoredId === null || recordStoredId === entryId || exactHolderId ? 'invalid' : { musicBrainzId: entryId, replaces: recordStoredId };
    if (recordStoredId === entryId || (exactHolderId && exactHolderId !== recordId)) return null;
    return recordStoredId === null ? { musicBrainzId: entryId, replaces: null } : null;
}
/** The writes of frozen identities in draft order (Artist entries, then the label), as the confirmation lists them. */
export function importMusicBrainzIdWrites(identities: Pick<ImportApprovedIdentities, 'artists' | 'label'>, draft: ImportDraftV2): ImportMusicBrainzIdWrite[] {
    const writes: ImportMusicBrainzIdWrite[] = [];
    for (const entry of draft.album.artists) {
        const write = identities.artists.find(artist => artist.entryKey === entry.key)?.musicBrainzIdWrite;
        if (write) writes.push({ scope: 'artist', entryKey: entry.key, musicBrainzId: write.musicBrainzId, replaces: write.replaces });
    }
    const label = identities.label?.musicBrainzIdWrite;
    if (draft.album.label && label) writes.push({ scope: 'label', entryKey: null, musicBrainzId: label.musicBrainzId, replaces: label.replaces });
    return writes;
}
const SHOWN_WRITE_KEYS = ['scope', 'entryKey', 'musicBrainzId', 'replaces'] as const;
/** The comparison key of one write a confirmation showed: exactly {scope, entryKey, musicBrainzId, replaces}; null when malformed. */
export function shownMusicBrainzIdWriteKey(value: unknown): string | null {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    const item = value as Record<string, unknown>;
    if (Object.keys(item).length !== SHOWN_WRITE_KEYS.length || !SHOWN_WRITE_KEYS.every(key => hasOwn(item, key))) return null;
    if (item.scope === 'artist' ? !uuid(item.entryKey) || item.entryKey !== item.entryKey.toLowerCase() : item.scope !== 'label' || item.entryKey !== null) return null;
    if (keepableMusicBrainzId(item.musicBrainzId) !== item.musicBrainzId) return null;
    if (item.replaces !== null && (keepableMusicBrainzId(item.replaces) !== item.replaces || item.replaces === item.musicBrainzId)) return null;
    return JSON.stringify(SHOWN_WRITE_KEYS.map(key => item[key]));
}
/** Whether a confirmation showed exactly the writes the approval computed (in any order). */
export function sameMusicBrainzIdWrites(shown: readonly unknown[], computed: readonly ImportMusicBrainzIdWrite[]): boolean {
    const keys = new Set(shown.map(shownMusicBrainzIdWriteKey)), expected = new Set(computed.map(write => JSON.stringify(SHOWN_WRITE_KEYS.map(key => write[key]))));
    return !keys.has(null) && keys.size === shown.length && keys.size === expected.size && [...expected].every(key => keys.has(key));
}

type NamedKind = 'artist' | 'organization';
const collections: Record<NamedKind, string> = { artist: 'artists', organization: 'organizations' };
/** Ready lifecycle, as identity candidates require it (adminImportIdentity.ts readyImportCandidate). */
const ready = (kind: NamedKind) => kind === 'artist' ? readyArtistLifecycleFilter : readyOrganizationLifecycleFilter;
/**
 * Who holds each ID and which ID each named record holds, read in `session`: `holders` maps `${kind}:${id}` to the ready record
 * holding it, `storedIds` maps `${kind}:${recordId}` to the keepable ID that ready record holds (null for none or a malformed one;
 * absent when the record is not ready). At most two queries per kind, each projecting only the ID.
 */
export type MusicBrainzIdState = { holders: ReadonlyMap<string, string>; storedIds: ReadonlyMap<string, string | null> };
export async function readMusicBrainzIdState(session: ClientSession, ids: readonly { kind: NamedKind; id: string }[],
    records: readonly { kind: NamedKind; id: string }[]): Promise<MusicBrainzIdState> {
    const db = getDb()!, holders = new Map<string, string>(), storedIds = new Map<string, string | null>();
    for (const kind of ['artist', 'organization'] as const) {
        const wanted = [...new Set(ids.filter(item => item.kind === kind).map(item => keepableMusicBrainzId(item.id)).filter((id): id is string => id !== null))];
        if (wanted.length) {
            const rows = await db.collection(collections[kind]).find({ $and: [ready(kind), { musicBrainzId: { $in: wanted } }] }, { session, projection: { musicBrainzId: 1 } })
                .limit(wanted.length).maxTimeMS(3_000).toArray();
            for (const row of rows) if (typeof row.musicBrainzId === 'string') holders.set(`${kind}:${row.musicBrainzId}`, row._id.toHexString());
        }
        const named = [...new Set(records.filter(item => item.kind === kind && /^[0-9a-f]{24}$/.test(item.id)).map(item => item.id))];
        if (named.length) {
            const rows = await db.collection(collections[kind]).find({ $and: [ready(kind), { _id: { $in: named.map(id => new ObjectId(id)) } }] }, { session, projection: { musicBrainzId: 1 } })
                .limit(named.length).maxTimeMS(3_000).toArray();
            for (const row of rows) storedIds.set(`${kind}:${row._id.toHexString()}`, keepableMusicBrainzId(row.musicBrainzId));
        }
    }
    return { holders, storedIds };
}
